/** The requested today is missing or not a valid yyyy-MM-dd date. */
public class InvalidTodayException extends Exception {
    public InvalidTodayException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.sheet;

import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

public class RespondWithSheet {
    public void respond(@PathVariable("sheet") String sheet, SheetClock clock, ObjectResponse<SheetResponse> response) {
        response.send(new SheetResponse(sheet, clock.today(sheet).toString()));
    }
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import net.officefloor.hq.app.period.PeriodCloser;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

public class SaveToday {
    public void save(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val LocalDate today,
            SheetClock clock, PeriodCloser closer, Rollup rollup) {
        Rollup.Snapshot before = rollup.take(sheet);
        clock.setToday(sheet, today);
        // Periods past their grace days close before the figures the today change moved are audited.
        closer.autoClose(sheet, user);
        rollup.record(sheet, user, before);
    }
}
package net.officefloor.hq.app.sheet;

import java.sql.Date;
import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;

/**
 * The sheet's "today". Every date decision and every default date in the app reads the date from
 * here, never from the real clock. A sheet starts at the real date until its today is set.
 */
@Service
public class SheetClock {

    private final JdbcTemplate jdbc;

    public SheetClock(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public LocalDate today(String sheet) {
        List<LocalDate> found = jdbc.query("SELECT today FROM sheet WHERE id = ?",
                (rs, i) -> rs.getDate(1).toLocalDate(), sheet);
        return found.isEmpty() ? LocalDate.now() : found.get(0);
    }

    public void setToday(String sheet, LocalDate today) {
        jdbc.update("MERGE INTO sheet (id, today) KEY (id) VALUES (?, ?)", sheet, Date.valueOf(today));
    }
}
package net.officefloor.hq.app.sheet;

/** A sheet as the screen shows it: its id and its today (ISO yyyy-MM-dd). */
public record SheetResponse(String id, String today) {
}
package net.officefloor.hq.app.sheet;

/** Body of POST /api/sheets/{sheet}/today: the new today (ISO yyyy-MM-dd). */
public record TodayRequest(String today) {
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateToday {
    public void validate(@RequestBody TodayRequest request, Out<LocalDate> today) throws InvalidTodayException {
        String raw = request == null || request.today() == null ? "" : request.today().trim();
        try {
            today.set(LocalDate.parse(raw));
        } catch (DateTimeParseException e) {
            throw new InvalidTodayException("Not a valid date: " + raw);
        }
    }
}
package net.officefloor.hq.app.role;

/** The role a user name has on a sheet: clerk (any name not given one), steward, or viewer (sees everything, changes nothing). */
public record Role(String user, String role) {

    public static final String CLERK = "clerk";
    public static final String STEWARD = "steward";
    public static final String VIEWER = "viewer";
}
package net.officefloor.hq.app.role;

import java.util.List;
import net.officefloor.hq.app.delegation.Delegations;
import net.officefloor.hq.app.sheet.SheetClock;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** The roles given per sheet, by user name; a name given none is a clerk. A user lent the steward role acts as one
 *  while the sheet's today is inside the delegation. */
@Repository
public class Roles {

    private static final RowMapper<Role> ROW = (rs, i) -> new Role(rs.getString("user_name"), rs.getString("role"));

    private final JdbcTemplate jdbc;
    private final Delegations delegations;
    private final SheetClock clock;

    public Roles(JdbcTemplate jdbc, Delegations delegations, SheetClock clock) {
        this.jdbc = jdbc;
        this.delegations = delegations;
        this.clock = clock;
    }

    /** Every role given on the sheet, by user name. */
    public List<Role> list(String sheet) {
        return jdbc.query("SELECT user_name, role FROM user_role WHERE sheet = ? ORDER BY user_name", ROW, sheet);
    }

    /** The role the user acts in on the sheet: steward while lent the role, else the role given. */
    public String of(String sheet, String user) {
        if (delegations.delegatorOn(sheet, user, clock.today(sheet)).isPresent()) {
            return Role.STEWARD;
        }
        return given(sheet, user);
    }

    /** The user's role given on the sheet: clerk unless given another. */
    public String given(String sheet, String user) {
        List<String> found = jdbc.queryForList("SELECT role FROM user_role WHERE sheet = ? AND user_name = ?",
                String.class, sheet, user);
        return found.isEmpty() ? Role.CLERK : found.get(0);
    }

    public void set(String sheet, Role role) {
        jdbc.update("MERGE INTO user_role (sheet, user_name, role) KEY (sheet, user_name) VALUES (?, ?, ?)", sheet,
                role.user(), role.role());
    }
}
